import { AbstractIterator, AbstractKeyIterator, AbstractLevel, AbstractValueIterator, } from 'abstract-level';
import ModuleError from 'module-error';
import Database from 'better-sqlite3';
const queryFromOptions = (options) => {
    let query = 'SELECT key, value FROM kv';
    const params = [];
    const conditions = [];
    if (options.gt != null) {
        conditions.push('key > ?');
        params.push(options.gt);
    }
    else if (options.gte != null) {
        conditions.push('key >= ?');
        params.push(options.gte);
    }
    if (options.lt != null) {
        conditions.push('key < ?');
        params.push(options.lt);
    }
    else if (options.lte != null) {
        conditions.push('key <= ?');
        params.push(options.lte);
    }
    if (conditions.length > 0) {
        query += ` WHERE ${conditions.join(' AND ')}`;
    }
    if (options.reverse) {
        query += ' ORDER BY key DESC';
    }
    else {
        query += ' ORDER BY key ASC';
    }
    if (options.limit != null && options.limit >= 0) {
        query += ` LIMIT ?`;
        params.push(options.limit);
    }
    return { query, params };
};
class SqliteIterator extends AbstractIterator {
    iterator;
    constructor(db, options, client) {
        super(db, options);
        const { query, params } = queryFromOptions(options);
        const stmt = client.prepare(query);
        this.iterator = stmt.iterate(...params);
    }
    async _next(callback) {
        const result = this.iterator.next();
        if (!result.done) {
            return this.db.nextTick(callback, null, result.value.key, result.value.value);
        }
        else {
            return this.db.nextTick(callback, null, undefined, undefined);
        }
    }
    _close(callback) {
        this.iterator.return?.();
        this.db.nextTick(callback);
    }
}
class SqliteKeyIterator extends AbstractKeyIterator {
    iterator;
    constructor(db, options, client) {
        super(db, options);
        const { query, params } = queryFromOptions(options);
        const stmt = client.prepare(query);
        this.iterator = stmt.iterate(...params);
    }
    async _next(callback) {
        const result = this.iterator.next();
        if (!result.done) {
            return this.db.nextTick(callback, null, result.value.key);
        }
        else {
            return this.db.nextTick(callback, null, undefined);
        }
    }
    _close(callback) {
        this.iterator.return?.();
        this.db.nextTick(callback);
    }
}
class SqliteValueIterator extends AbstractValueIterator {
    iterator;
    constructor(db, options, client) {
        super(db, options);
        const { query, params } = queryFromOptions(options);
        const stmt = client.prepare(query);
        this.iterator = stmt.iterate(...params);
    }
    async _next(callback) {
        const result = this.iterator.next();
        if (!result.done) {
            return this.db.nextTick(callback, null, result.value.value);
        }
        else {
            return this.db.nextTick(callback, null, undefined);
        }
    }
    _close(callback) {
        this.iterator.return?.();
        this.db.nextTick(callback);
    }
}
export class SqliteLevel extends AbstractLevel {
    db;
    readOnly = false;
    constructor(options) {
        const encodings = { utf8: true };
        super({ encodings }, options);
        this.db = new Database(options.filename);
        this.db.pragma('journal_mode = WAL');
        if (options.readOnly !== undefined) {
            this.readOnly = options.readOnly;
        }
    }
    get type() {
        return 'sqlite3';
    }
    async _open(options, callback) {
        this.db.exec('CREATE TABLE IF NOT EXISTS kv (key TEXT UNIQUE, value TEXT)');
        this.nextTick(callback);
    }
    async _close(callback) {
        this.db.close();
        this.nextTick(callback);
    }
    async _get(key, options, callback) {
        const stmt = this.db.prepare('SELECT value FROM kv WHERE key = ?');
        const row = stmt.get(key.toString());
        if (row) {
            return this.nextTick(callback, null, row.value);
        }
        else {
            return this.nextTick(callback, new ModuleError(`Key ${key} was not found`, {
                code: 'LEVEL_NOT_FOUND',
            }));
        }
    }
    async _put(key, value, options, callback) {
        if (this.readOnly) {
            return this.nextTick(callback, new ModuleError('not authorized to write to branch', {
                code: 'LEVEL_READ_ONLY',
            }));
        }
        const stmt = this.db.prepare('INSERT INTO kv (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value');
        stmt.run(key.toString(), value.toString());
        this.nextTick(callback);
    }
    async _del(key, options, callback) {
        if (this.readOnly) {
            return this.nextTick(callback, new ModuleError('not authorized to write to branch', {
                code: 'LEVEL_READ_ONLY',
            }));
        }
        const stmt = this.db.prepare('DELETE FROM kv WHERE key = ?');
        stmt.run(key.toString());
        this.nextTick(callback);
    }
    async _batch(batch, options, callback) {
        if (this.readOnly) {
            return this.nextTick(callback, new ModuleError('not authorized to write to branch', {
                code: 'LEVEL_READ_ONLY',
            }));
        }
        const putStmt = this.db.prepare('INSERT INTO kv (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value');
        const delStmt = this.db.prepare('DELETE FROM kv WHERE key = ?');
        const runBatch = this.db.transaction((ops) => {
            for (const op of ops) {
                if (op.type === 'put') {
                    putStmt.run(op.key.toString(), op.value.toString());
                }
                else if (op.type === 'del') {
                    delStmt.run(op.key.toString());
                }
            }
        });
        runBatch(batch);
        this.nextTick(callback);
    }
    async _clear(options, callback) {
        if (this.readOnly) {
            return this.nextTick(callback, new ModuleError('not authorized to write to branch', {
                code: 'LEVEL_READ_ONLY',
            }));
        }
        let query = 'DELETE FROM kv';
        const params = [];
        const conditions = [];
        if (options.gt != null) {
            conditions.push('key > ?');
            params.push(options.gt);
        }
        else if (options.gte != null) {
            conditions.push('key >= ?');
            params.push(options.gte);
        }
        if (options.lt != null) {
            conditions.push('key < ?');
            params.push(options.lt);
        }
        else if (options.lte != null) {
            conditions.push('key <= ?');
            params.push(options.lte);
        }
        if (conditions.length > 0) {
            query += ` WHERE ${conditions.join(' AND ')}`;
        }
        const stmt = this.db.prepare(query);
        stmt.run(...params);
        this.nextTick(callback);
    }
    _iterator(options) {
        return new SqliteIterator(this, options, this.db);
    }
    _keys(options) {
        return new SqliteKeyIterator(this, options, this.db);
    }
    _values(options) {
        return new SqliteValueIterator(this, options, this.db);
    }
}
